self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))
      ))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // NAVIGATIONS ARE NETWORK-FIRST. Everything else is cache-first.
  //
  // Cache-first on the document is how a viewer ends up presenting a deck that
  // was superseded hours ago: the worker answers from cache before the network
  // is ever consulted, so a republish is invisible until the worker itself
  // updates. That is belt to CACHE_NAME's braces — the cache key is now
  // content-addressed, so a republish DOES roll it, but a cache key is only
  // load-bearing while it is correct, and it was wrong for weeks without
  // anything noticing.
  //
  // The offline guarantee is untouched: the network attempt falls back to the
  // cached copy, so a room with no wifi still gets the deck. The cost is one
  // conditional request per navigation when online, which is nothing next to
  // standing in front of an audience presenting the wrong version.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() => caches.match(request, { ignoreSearch: true })
          .then((hit) => hit || caches.match('index.html')))
    );
    return;
  }

  event.respondWith(
    caches.match(request, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(request).catch(() => Response.error());
    })
  );
});
